enum { UNDO_HASH_SIZE = 32, };  ///< Size in bytes of the hash used in the undo file.

typedef struct u_header u_header_T;

typedef struct u_entry u_entry_T;
struct u_entry {
  u_entry_T *ue_next;  ///< pointer to next entry in list
  linenr_T ue_top;     ///< number of line above undo block
  linenr_T ue_bot;     ///< number of line below undo block
  linenr_T ue_lcount;  ///< linecount when u_save called
  char **ue_array;     ///< array of lines in undo block
  linenr_T ue_size;    ///< number of lines in ue_array
#ifdef U_DEBUG
  int ue_magic;        ///< magic number to check allocation
#endif
};

struct u_header {
  // The following have a pointer and a number. The number is used when reading
  // the undo file in u_read_undo()
  union {
    u_header_T *ptr;              ///< pointer to next undo header in list
    int seq;
  } uh_next;
  union {
    u_header_T *ptr;              ///< pointer to previous header in list
    int seq;
  } uh_prev;
  union {
    u_header_T *ptr;              ///< pointer to next header for alt. redo
    int seq;
  } uh_alt_next;
  union {
    u_header_T *ptr;              ///< pointer to previous header for alt. redo
    int seq;
  } uh_alt_prev;
  int uh_seq;                     ///< sequence number, higher == newer undo
  int uh_walk;                    ///< used by undo_time()
  u_entry_T *uh_entry;            ///< pointer to first entry
  u_entry_T *uh_getbot_entry;     ///< pointer to where ue_bot must be set
  pos_T uh_cursor;                ///< Pre-change cursor pos; restored on undo.
  pos_T uh_cursor_after;          ///< Post-change pos; restored on redo. Not saved to undofile.
  colnr_T uh_cursor_vcol;         ///< Virtual column of uh_cursor ('virtualedit'), or -1.
  int uh_flags;                   ///< see below
  fmark_T uh_namedm[NMARKS];      ///< marks before undo/after redo
  extmark_undo_vec_t uh_extmark;  ///< info to move extmarks
  visualinfo_T uh_visual;         ///< Visual areas before undo/after redo
  time_t uh_time;                 ///< timestamp when the change was made
  int uh_save_nr;                 ///< set when the file was saved after the
                                  ///< changes in this block
#ifdef U_DEBUG
  int uh_magic;                   ///< magic number to check allocation
#endif
};

/// values for uh_flags
enum {
  UH_CHANGED  = 0x01,  ///< b_changed flag before undo/after redo
  UH_EMPTYBUF = 0x02,  ///< buffer was empty
  UH_RELOAD   = 0x04,  ///< buffer was reloaded
};

/// Checkpoint of buffer undo state, for "undo-invisible" speculative edits: u_checkpoint() detaches
/// the undo tree so subsequent edits build a disposable one; u_rollback() reverts those edits and
/// reattaches the checkpointed tree.  Used by 'inccommand' preview.
typedef struct {
  u_header_T *uc_oldhead;
  u_header_T *uc_newhead;
  u_header_T *uc_curhead;
  int uc_numhead;
  bool uc_synced;
  int uc_seq_last;
  int uc_save_nr_last;
  int uc_seq_cur;
  time_t uc_time_cur;
  int uc_save_nr_cur;
  char *uc_line_ptr;
  linenr_T uc_line_lnum;
  colnr_T uc_line_colnr;
  OptInt uc_undolevels;        ///< saved 'undolevels'
  varnumber_T uc_changedtick;  ///< saved b:changedtick
} UndoCheckpoint;

if (wysihtml5.browser.supportsCommand(document, "insertHTML")) {

  module("wysihtml5.UndoManager", {
    setup: function() {
      this.textareaElement        = document.createElement("textarea");
      this.textareaElement.value  = "1";

      this.form = document.createElement("form");
      this.form.onsubmit = function() { return false; };
      this.form.appendChild(this.textareaElement);

      document.body.appendChild(this.form);
    },

    teardown: function() {
      var leftover;
      while (leftover = document.querySelector("iframe.wysihtml5-sandbox, input[name='_wysihtml5_mode']")) {
        leftover.parentNode.removeChild(leftover);
      }
      this.form.parentNode.removeChild(this.form);
    },

    triggerUndo: function(editor) {
      this.triggerKey(editor, 90);
    },

    triggerRedo: function(editor) {
      this.triggerKey(editor, 89);
    },

    triggerKey: function(editor, keyCode) {
      var event;
      try {
        event = editor.composer.sandbox.getDocument().createEvent("KeyEvents");
        event.initKeyEvent("keydown", true, true, editor.composer.sandbox.getWindow(), true, false, false, false, keyCode, keyCode);
      } catch(e) {
        event = editor.composer.sandbox.getDocument().createEvent("Events");
        event.initEvent("keydown", true, true);
        event.ctrlKey = true;
        event.keyCode = keyCode;
      }
      editor.composer.element.dispatchEvent(event);
    }
  });


  asyncTest("Basic test", function() {
    expect(5);

    var that   = this;
    // editor = new wysihtml5.Editor(this.textareaElement);
    $(this.textareaElement).wysihtml5();
    var editor = $(this.textareaElement).data('wysihtml5').editor;

    editor.on("load", function() {
      editor.setValue("1 2").fire("newword:composer");
      editor.setValue("1 2 3").fire("newword:composer");
      editor.setValue("1 2 3 4").fire("newword:composer");
      editor.setValue("1 2 3 4 5");

      that.triggerUndo(editor);
      equal(editor.getValue(), "1 2 3 4");
      that.triggerRedo(editor);
      that.triggerRedo(editor);
      equal(editor.getValue(), "1 2 3 4 5");
      that.triggerUndo(editor);
      that.triggerUndo(editor);
      equal(editor.getValue(), "1 2 3");
      that.triggerUndo(editor);
      that.triggerUndo(editor);
      equal(editor.getValue(), "1");
      that.triggerUndo(editor);
      that.triggerUndo(editor);
      equal(editor.getValue(), "1");

      start();
    });
  });


  asyncTest("Test commands", function() {
    expect(3);

    var that   = this;
    // editor = new wysihtml5.Editor(this.textareaElement);
    $(this.textareaElement).wysihtml5();
    var editor = $(this.textareaElement).data('wysihtml5').editor;

    editor.on("load", function() {
      editor.setValue("<b>1</b>").fire("beforecommand:composer");
      editor.setValue("<i><b>1</b></i>").fire("beforecommand:composer");

      that.triggerUndo(editor);
      equal(editor.getValue(), "<b>1</b>");
      that.triggerRedo(editor);
      equal(editor.getValue(), "<i><b>1</b></i>");
      that.triggerUndo(editor);
      that.triggerUndo(editor);
      equal(editor.getValue(), "1");

      start();
    });
  });
}

